import type { ProjectStaffingStatus } from '~/client';

interface ProjectStaffingStatusEntry {
  label: string;
  color: string;
}

// Key order defines the user-visible select order (Active, Not Active).
export const projectStaffingStatusConfig: Record<ProjectStaffingStatus, ProjectStaffingStatusEntry> = {
  active: { label: 'Active', color: 'bg-green-200 text-green-600' },
  finished: { label: 'Not Active', color: 'bg-blue-200 text-blue-600' },
};

const defaultProjectStaffingStatus: ProjectStaffingStatusEntry = { label: '', color: 'bg-gray-200 text-gray-800' };

export function getProjectStaffingStatus(status: ProjectStaffingStatus): ProjectStaffingStatusEntry {
  return (
    projectStaffingStatusConfig[status] ?? {
      ...defaultProjectStaffingStatus,
      label: snakeCaseToCapitalizedCase(status),
    }
  );
}

// The 'all' sentinel stays first; consumers call `.slice(1)` to drop it for the edit form.
export const projectStaffingStatuses: SelectItem<ProjectStaffingStatus | 'all'>[] = [
  { name: 'All Staffing Statuses', value: 'all' },
  ...Object.entries(projectStaffingStatusConfig).map(([value, { label }]) => ({
    value: value as ProjectStaffingStatus,
    name: label,
  })),
];
